/// <summary>
/// Custom editor that safely handles the .NET 9 breaking change where
/// IWindowsFormsEditorService.DropDownControl now throws ArgumentNullException
/// when passed null.
/// </summary>
internal class SafeDropDownEditor : UITypeEditor
{
    public override UITypeEditorEditStyle GetEditStyle(ITypeDescriptorContext context)
        => UITypeEditorEditStyle.DropDown;

    public override object EditValue(ITypeDescriptorContext context,
        IServiceProvider provider, object value)
    {
        var editorService = provider?.GetService(typeof(IWindowsFormsEditorService))
            as IWindowsFormsEditorService;
        if (editorService == null) return value;

        Control dropDown = BuildDropDown(value);

        // .NET 9: DropDownControl throws ArgumentNullException when passed null.
        if (dropDown != null)
        {
            editorService.DropDownControl(dropDown);
            value = dropDown.Tag;
        }

        return value;
    }

    private static Control BuildDropDown(object currentValue)
    {
        var listBox = new ListBox();
        listBox.Items.Add("Option A");
        listBox.Items.Add("Option B");
        listBox.Tag = currentValue;
        listBox.SelectedIndexChanged += (s, e) =>
        {
            var lb = (ListBox)s;
            lb.Tag = lb.SelectedItem;
        };
        return listBox;
    }
}

